CREATE OR REPLACE FUNCTION pg_temp.k(t text) RETURNS text LANGUAGE sql IMMUTABLE AS $$
  SELECT translate(lower(replace(replace(coalesce(t,''),'İ','i'),'I','ı')),'çğıöşüâî','cgiosuai') $$;
-- İlçe adı birden çok ilde geçiyorsa (ör. "Merkez", "Yenişehir") ilçeden il çıkarılmaz
CREATE TEMP TABLE ilce_tek AS
  SELECT pg_temp.k(ilce) k, min(il) il FROM ilce_il GROUP BY 1 HAVING count(DISTINCT il) = 1;
-- OSM il adları resmî yazımda mı? (eşleşmeyen il adı ilce_tek'te sessizce yanlış il yazardı)
SELECT 'OSM il adı listede yok: ' || il FROM (SELECT DISTINCT il FROM ilce_il) x
WHERE il NOT IN (SELECT DISTINCT il FROM core.eczane_hedef);

-- 1) Sabit hat alan kodu (cep numarası 5xx il söylemez)
UPDATE raw.eczane_kaynak k SET il = a.il FROM alan_kodu a
WHERE k.kaynak = 'OVERTURE' AND k.il IS NULL AND left(k.telefonlar[1], 3) = a.kod;
-- 2) İlçe adı (tekil ise)
UPDATE raw.eczane_kaynak k SET il = t.il FROM ilce_tek t
WHERE k.kaynak = 'OVERTURE' AND k.il IS NULL AND pg_temp.k(k.ilce) = t.k
  AND t.il IN (SELECT DISTINCT il FROM core.eczane_hedef);
SELECT count(*) FILTER (WHERE il IS NULL) hala_ilsiz, count(*) FILTER (WHERE hedef_id IS NULL AND il IS NOT NULL) esleyecek
FROM raw.eczane_kaynak WHERE kaynak = 'OVERTURE';

-- Eczane olmayan sızıntılar: Overture birincil kategorisi pharmacy olsa da adında
-- eczane izi olmayan YENİ hedefler (ör. "Kardeş Optik") kampanyaya girmez.
UPDATE core.eczane_hedef SET durum = 'GECERSIZ', guncellendi = now()
WHERE kaynak = 'OVERTURE' AND durum = 'YENI'
  AND pg_temp.k(eczane) !~ '(ecz|pharm|apotek|eczane)';
COMMIT;
